// 2:1 multiplexer, used to select between the three independent flip-flops
// (q[0], q[1], q[2]) and the input r, according to the control signal L.
module TopModule (
    input [2:0] r,
    input L,
    input [2:0] q,
    output reg [2:0] q_out);

  always @(*) begin
    if (L) q_out = r;
    else   q_out = {q[1] ^ q[2], q[0], q[2]};
  end

endmodule

