// 2:1 multiplexer
module TopModule (
    input [2:0] r,
    input [2:0] q_in,
    input L,
    output [2:0] q
);
    wire [2:0] q_reg;
    wire [2:0] q_next;
    assign q_next = {q_reg[1] ^ q_reg[2], q_reg[0], q_reg[2]};
    always @(*) begin
        if (L) q_reg = r;
        else q_reg = q_next;
    end
    assign q = q_reg;
endmodule

