// 2:1 multiplexer, instantiated three times in full_module, factorised into a
// separate module named "TopModule".
module TopModule (
    input [2:0] r,
    input L,
    input clk,
    output reg [2:0] q,
    input q_in,
    input r_in,
    output reg Q);

  always @(posedge clk) begin
    if (L) begin
      q <= r;
    end else begin
      q <= {q[1] ^ q[2], q[0], q[2]};
    end
    Q <= q_in & r_in;
  end

endmodule

